const BLANK = (r, c) => Array.from({ length: r }, () => Array(c).fill(''));
const row = (vals, r, from = 0) => Object.fromEntries(vals.map((v, i) => [`${r},${from + i}`, String(v)]));

module.exports = {
  id: 'eigenvalues', title: 'Eigenvalues and Eigenvectors', sub: 'Characteristic equation, trace and determinant shortcuts, diagonalisation and properties', cat: 'Engineering Mathematics',
  accent: '#4f8cff', icon: 'gauge', target: 30, keyword: 'EIGEN', tags: '#gate2027 #gatecse #eigenvalues #linearalgebra',
  scenes: [
    { type: 'hook', title: 'Eigenvalues and Eigenvectors', kicker: 'Engineering Mathematics · 30 minutes', q: 'A 2 by 2 matrix has trace 7 and determinant 10. What are its eigenvalues?',
      n: 'A two by two matrix has trace seven and determinant ten. What are its eigenvalues? You could expand a determinant. Or you could answer in five seconds. Picture a rubber sheet that is stretched and sheared. Almost every direction gets turned, but a few special directions only get longer or shorter. Those are eigenvectors, and the stretch factors are eigenvalues. GATE asks you to find them fast using trace and determinant, to decide when a matrix can be diagonalised, and to see what powers, inverses, triangular and symmetric matrices do to them. In the next thirty minutes we build it visually, with tables that fill as we solve, and the traps examiners love. Every number on screen was verified by computer. And the answer to the opening question is five and two.' },
    { type: 'roadmap', n: 'Here is the plan. Forty four short steps in eight sections: the idea, the characteristic equation, trace and determinant shortcuts, eigenvectors and multiplicity, diagonalisation, properties of special matrices, GATE traps, and finally GATE practice with shortcuts.' },
    { type: 'step', x: 1, chip: 'Analogy', title: 'Think of a stretching sheet', icon: 'layers',
      items: [['arrow', 'Matrix = a stretch of the plane', 'every vector is moved somewhere'], ['eye', 'Most vectors turn', 'they leave their own line'], ['key', 'Eigenvectors stay on their line', 'only their length changes'], ['gauge', 'Eigenvalue = the stretch factor', 'negative means flipped']],
      n: 'Here is a picture to keep in mind. A matrix stretches and shears the whole plane. Most vectors get moved off their own line. Eigenvectors are the special ones that stay on their line, and only their length changes. The eigenvalue is the stretch factor, and a negative eigenvalue means the vector is flipped around.' },

    { sec: 'The idea', title: 'A vector that keeps its direction', viz: { kind: 'grid', corner: 'vector', rows: ['v', 'A v', 'w', 'A w'], hw: 190, cols: ['x', 'y', 'Direction'], cw: 330, fs: 50, rh: 100, cells: BLANK(4, 3), tint: { 'same line': 'ok', 'turned': 'bad' },
        steps: [{ k: 'start with the vector', set: row([1, 1], 0), hl: ['r0'], col: 'blue', note: 'v = (1, 1), and A = [[4, 1], [2, 3]]' }, { k: 'multiply by A', set: row([5, 5, 'same line'], 1), hl: ['r1'], clear: true, col: 'ok', note: 'A v = (5, 5) = 5 · v' }, { k: 'now try', set: row([1, 0], 2), hl: ['r2'], clear: true, col: 'pink', note: 'w = (1, 0)' }, { k: 'it turns', set: row([4, 2, 'turned'], 3), hl: ['r3'], clear: true, col: 'bad', note: 'A w = (4, 2) is not a multiple of w' }] },
      tip: 'Eigenvector: A v = λ v with v not zero. Here λ = 5.',
      n: 'Step one. Take the matrix four, one, two, three. Start with the vector one, one. Multiply by A and we get five, five, which is exactly five times the original. Same line, only longer. Now try the vector one, zero. It maps to four, two. It turns, and is not a multiple of the original. So one, one is an eigenvector with eigenvalue five, and one, zero is not an eigenvector at all.' },
    { sec: 'The idea', title: 'The vocabulary', cols: ['Term', 'Meaning'],
      rows: [['Eigenvector v', 'non-zero, with A v = λ v'], ['Eigenvalue λ', 'the scalar in that equation'], ['Eigenspace', 'all v for one λ, plus the zero vector'], ['Spectrum', 'the set of all eigenvalues'], ['Multiplicity', 'how often λ repeats as a root']],
      firstW: 330, tip: 'The zero vector is never called an eigenvector, but zero can be an eigenvalue.',
      n: 'Step two: the vocabulary. An eigenvector is a non zero vector with A v equal to lambda v. The eigenvalue is that scalar lambda. The eigenspace collects every vector for one eigenvalue, plus the zero vector. The spectrum is the set of all eigenvalues. And multiplicity is how often an eigenvalue repeats as a root. The zero vector is never an eigenvector, but zero itself can certainly be an eigenvalue.' },
    { sec: 'The idea', title: 'Why the determinant is zero', icon: 'key',
      items: [['arrow', 'A v = λ v', 'start from the definition'], ['wrench', '(A − λ I) v = 0', 'move everything to one side'], ['lock', 'v must not be zero', 'so A − λ I cannot be invertible'], ['hash', 'det(A − λ I) = 0', 'the characteristic equation']],
      tip: 'A − λ I has a non-zero null vector exactly when it is singular.',
      n: 'Step three: why the determinant is zero. Start from A v equals lambda v. Move everything to one side, to get A minus lambda I, times v, equals zero. We need a non zero v. That is only possible when A minus lambda I is singular, which means its determinant is zero. That equation is the characteristic equation, and its roots are the eigenvalues.' },

    { sec: 'Characteristic equation', title: 'Solve it for our matrix', viz: { kind: 'grid', corner: 'step', rows: ['write', 'expand', 'simplify', 'factor'], hw: 190, cols: ['det(A − λ I) for A = [[4, 1], [2, 3]]'], cw: 1100, fs: 46, rh: 92, cells: BLANK(4, 1),
        steps: [{ k: 'subtract lambda from the diagonal', set: row(['(4 − λ)(3 − λ) − 1 · 2'], 0), hl: ['r0'], col: 'blue', note: 'det of [[4 − λ, 1], [2, 3 − λ]]' }, { k: 'expand', set: row(['12 − 7λ + λ² − 2'], 1), hl: ['r1'], clear: true, col: 'pink' }, { k: 'simplify', set: row(['λ² − 7λ + 10'], 2), hl: ['r2'], clear: true, col: 'warn' }, { k: 'factor', set: row(['(λ − 5)(λ − 2) = 0'], 3), hl: ['r3'], clear: true, col: 'ok', note: 'eigenvalues: λ = 5 and λ = 2' }] },
      tip: 'An n by n matrix gives a degree n polynomial, so at most n eigenvalues.',
      n: 'Step four: solve it. Subtract lambda from the diagonal and take the determinant: four minus lambda times three minus lambda, minus one times two. Expand: twelve minus seven lambda plus lambda squared minus two. Simplify to lambda squared minus seven lambda plus ten. Then factor into lambda minus five times lambda minus two. So the eigenvalues are five and two.' },
    { sec: 'Characteristic equation', title: 'Eigenvalues are roots', viz: { kind: 'plot', x: [0, 7], y: [-4, 12], xt: 1, yt: 4, fns: [{ f: 'x*x-7*x+10' }],
        steps: [{ k: 'plot the characteristic polynomial', note: 'p(λ) = λ² − 7λ + 10', col: 'blue' }, { k: 'crosses zero at two', pt: [[2, 0, 'λ = 2']], vline: [2], col: 'ok', note: 'p(2) = 4 − 14 + 10 = 0' }, { k: 'and at five', pt: [[5, 0, 'λ = 5']], vline: [5], col: 'ok', note: 'p(5) = 25 − 35 + 10 = 0' }, { k: 'between them', note: 'p(3) = 9 − 21 + 10 = −2, so it dips below zero', col: 'warn' }] },
      tip: 'Real eigenvalues are the places where p(λ) crosses the axis.',
      n: 'Step five: look at it. Plot the characteristic polynomial, lambda squared minus seven lambda plus ten. It crosses zero at two, so lambda equals two is an eigenvalue. And at five, the second eigenvalue. Between them the curve dips below zero, for instance at three, where it equals minus two. Real eigenvalues are simply the places where this curve meets the axis.' },
    { sec: 'Characteristic equation', title: 'Find the eigenvectors', viz: { kind: 'grid', corner: 'solve', rows: ['λ', 'A − λ I', 'null space', 'eigenvector'], hw: 200, cols: ['λ = 5', 'λ = 2'], cw: 700, fs: 46, rh: 92, cells: BLANK(4, 2),
        steps: [{ k: 'for each eigenvalue', set: row(['5', '2'], 0), hl: ['r0'], col: 'blue', note: 'solve (A − λ I) v = 0 once per eigenvalue' }, { k: 'subtract', set: row(['[[−1, 1], [2, −2]]', '[[2, 1], [2, 1]]'], 1), hl: ['r1'], clear: true, col: 'pink' }, { k: 'each matrix has two equal rows', set: row(['−x + y = 0', '2x + y = 0'], 2), hl: ['r2'], clear: true, col: 'warn', note: 'rank 1 each time: one free variable' }, { k: 'so the eigenvectors are', set: row(['(1, 1)', '(1, −2)'], 3), hl: ['r3'], clear: true, col: 'ok', note: 'check: A(1, −2) = (2, −4) = 2 · (1, −2)' }] },
      tip: 'Any non-zero multiple of an eigenvector is also an eigenvector.',
      n: 'Step six: eigenvectors. For each eigenvalue, solve A minus lambda I times v equals zero. Subtract five from the diagonal, and subtract two. Each matrix has two equal rows, so the rank is one and there is one free variable. Minus x plus y equals zero, and two x plus y equals zero. So the eigenvectors are one, one, and one, minus two. Check the second: A times one, minus two is two, minus four, twice the vector.' },
    { sec: 'Characteristic equation', title: 'Verification', cmd: ['A = [[4, 1], [2, 3]]', 'A · (1, 1)  = (5, 5)    = 5 · (1, 1)    ✓', 'A · (1, −2) = (2, −4)   = 2 · (1, −2)   ✓', 'trace = 4 + 3 = 7 = 5 + 2              ✓', 'det   = 12 − 2 = 10 = 5 · 2            ✓', '# exact rational arithmetic, no rounding'],
      term: 'verify', tip: 'Always check A v = λ v and trace and determinant: ten seconds.',
      n: 'Step seven: a quick verification. A times one, one gives five, five, which is five times the vector. A times one, minus two gives two, minus four, twice the vector. The trace is four plus three, seven, which equals five plus two. The determinant is twelve minus two, ten, which equals five times two. All checked with exact arithmetic. In an exam, this check takes ten seconds and catches every sign error.' },

    { sec: 'Shortcuts', title: 'Trace and determinant', cols: ['Quantity', 'Equals', 'Why'],
      rows: [['Trace', 'sum of eigenvalues', 'coefficient of λⁿ⁻¹'], ['Determinant', 'product of eigenvalues', 'constant term, up to sign'], ['2 × 2 polynomial', 'λ² − tr · λ + det', 'one line, no expansion'], ['Complex roots', 'still counted', 'sum and product both hold']],
      firstW: 330, tip: 'Both identities hold with multiplicity, and with complex eigenvalues.',
      n: 'Step eight: the two big shortcuts. The trace equals the sum of the eigenvalues, and the determinant equals their product. For a two by two matrix this means the characteristic polynomial is simply lambda squared minus trace times lambda plus determinant, with no expansion at all. Both identities count repeated roots as many times as they repeat, and both still hold when eigenvalues are complex.' },
    { sec: 'Shortcuts', title: 'The five-second method', viz: { kind: 'array', cells: ['?', '?', '?', '?'], label: '', cw: 260, idx: false, fs: 50,
        steps: [{ k: 'a matrix has trace', set: { 0: '7' }, hl: [0], col: 'blue', note: 'trace = 7: the eigenvalues add to 7' }, { k: 'and determinant', set: { 1: '10' }, hl: [1], col: 'pink', note: 'determinant = 10: they multiply to 10' }, { k: 'we need two numbers', set: { 2: '5', 3: '2' }, hl: [2, 3], clear: true, col: 'ok', note: '5 + 2 = 7 and 5 × 2 = 10' }, { k: 'no determinant expansion', ok: [2, 3], col: 'ok', note: 'eigenvalues 5 and 2, found by inspection' }] },
      tip: 'Cells show: trace, determinant, λ₁, λ₂. Find the pair by mental factoring.',
      n: 'Step nine: the five second method. A matrix has trace seven and determinant ten. We need two numbers that add to seven and multiply to ten. Five and two, by inspection. That is the opening question answered, with no determinant expansion at all. The four cells show trace, determinant, and the two eigenvalues, in that order. Practise this mental factoring until it is automatic. If the numbers do not factor nicely, fall back on the quadratic formula, and a negative discriminant means complex eigenvalues.' },
    { sec: 'Shortcuts', title: 'Three by three', viz: { kind: 'grid', corner: 'quantity', rows: ['trace', 'determinant', 'sum of 2×2 minors', 'polynomial'], hw: 280, cols: ['A = [[2, 1, 0], [1, 2, 0], [0, 0, 2]]'], cw: 1000, fs: 46, rh: 92, cells: BLANK(4, 1),
        steps: [{ k: 'the trace is', set: row(['2 + 2 + 2 = 6'], 0), hl: ['r0'], col: 'blue', note: 'λ₁ + λ₂ + λ₃ = 6' }, { k: 'the determinant is', set: row(['2 · (4 − 1) = 6'], 1), hl: ['r1'], clear: true, col: 'pink', note: 'λ₁ λ₂ λ₃ = 6' }, { k: 'the principal minors', set: row(['3 + 4 + 4 = 11'], 2), hl: ['r2'], clear: true, col: 'warn', note: 'minors of rows and columns (1,2), (1,3), (2,3)' }, { k: 'so the polynomial is', set: row(['λ³ − 6λ² + 11λ − 6 = (λ − 1)(λ − 2)(λ − 3)'], 3), hl: ['r3'], clear: true, col: 'ok', note: 'eigenvalues 1, 2, 3' }] },
      tip: 'λ³ − (trace) λ² + (sum of 2×2 principal minors) λ − det.',
      n: 'Step ten: three by three. The trace is two plus two plus two, six. The determinant is two times four minus one, six. Now the principal minors, the two by two determinants from rows and columns one two, one three, and two three: three, four, and four, which sum to eleven. So the polynomial is lambda cubed minus six lambda squared plus eleven lambda minus six, which factors as one, two, three. The eigenvalues are one, two, and three.' },
    { sec: 'Shortcuts', title: 'Constant row sums', icon: 'zap',
      items: [['list', 'Every row sums to s', 'then (1, 1, ..., 1) is an eigenvector'], ['gauge', 'The eigenvalue is s', 'because A · 1 = s · 1'], ['hash', 'Example: all row sums 4', '[[2,1,1],[1,2,1],[1,1,2]] has eigenvalue 4'], ['scale', 'Then use the trace', 'other two eigenvalues add to 6 − 4 = 2']],
      tip: 'Stochastic matrices always have eigenvalue 1. Columns summing to s give the same eigenvalue for Aᵀ.',
      n: 'Step eleven: a hidden shortcut. If every row of a matrix sums to the same number s, then the all ones vector is an eigenvector with eigenvalue s, because A times the ones vector gives s times the ones vector. Example: the matrix with two on the diagonal and one everywhere else. Every row sums to four, so four is an eigenvalue. Then use the trace, six, to see the other two add to two. They are both one. Stochastic matrices therefore always have eigenvalue one.' },

    { sec: 'Eigenvectors', title: 'Distinct eigenvalues', icon: 'users',
      items: [['users', 'Different λ, different eigenvectors', 'they are linearly independent'], ['check', 'n distinct eigenvalues', 'n independent eigenvectors: diagonalisable'], ['x', 'The converse is false', 'repeated eigenvalues may still work'], ['key', 'Same λ: eigenspace', 'a whole subspace, not one vector']],
      tip: 'Distinct eigenvalues is sufficient for diagonalisation, never necessary.',
      n: 'Step twelve: independence. Eigenvectors that belong to different eigenvalues are always linearly independent. So if an n by n matrix has n distinct eigenvalues, it has n independent eigenvectors and can be diagonalised. But the converse is false: a matrix with repeated eigenvalues may still be diagonalisable. And for a single eigenvalue the eigenvectors form a whole subspace, the eigenspace, not just one vector.' },
    { sec: 'Eigenvectors', title: 'A repeated eigenvalue that fails', viz: { kind: 'grid', corner: 'matrix', rows: ['A', 'A − 2I', 'null space', 'dimension'], hw: 220, cols: ['A = [[2, 1], [0, 2]]'], cw: 900, fs: 46, rh: 92, cells: BLANK(4, 1),
        steps: [{ k: 'the characteristic polynomial', set: row(['(λ − 2)² = 0, so λ = 2 twice'], 0), hl: ['r0'], col: 'blue', note: 'trace 4, determinant 4' }, { k: 'subtract two', set: row(['[[0, 1], [0, 0]]'], 1), hl: ['r1'], clear: true, col: 'pink' }, { k: 'only one free variable', set: row(['y = 0, so only (1, 0)'], 2), hl: ['r2'], clear: true, col: 'warn' }, { k: 'one eigenvector for two roots', set: row(['1 independent eigenvector'], 3), hl: ['r3'], clear: true, col: 'bad', note: 'not diagonalisable: a defective matrix' }] },
      tip: 'Defective: fewer independent eigenvectors than the matrix size.',
      n: 'Step thirteen: a repeated eigenvalue that fails. Take two, one, zero, two. The characteristic polynomial is lambda minus two, squared, so two appears twice. Subtract two from the diagonal and we get zero, one, zero, zero. There is only one free variable, so the only eigenvector is one, zero. We have one eigenvector for two roots, so the matrix cannot be diagonalised. It is called defective.' },
    { sec: 'Eigenvectors', title: 'A double root touches the axis', viz: { kind: 'plot', x: [-1, 5], y: [-2, 8], xt: 1, yt: 2, fns: [{ f: '(x-2)*(x-2)' }],
        steps: [{ k: 'a double root', note: 'p(λ) = (λ − 2)² touches the axis and bounces back', col: 'blue' }, { k: 'touches the axis', pt: [[2, 0, 'λ = 2, twice']], vline: [2], col: 'warn', note: 'the curve never goes below zero' }, { k: 'the same polynomial', note: 'both [[2, 1], [0, 2]] and 2I have p(λ) = (λ − 2)²', col: 'pink' }, { k: 'only the eigenspace', note: 'the polynomial alone cannot tell them apart', col: 'bad' }] },
      tip: 'Same characteristic polynomial does not mean the same diagonalisability.',
      n: 'Step fourteen: what a double root looks like. The polynomial lambda minus two, squared, touches the axis at two and bounces back, and never goes below zero. Now here is the catch. The defective matrix from before and two times the identity have exactly the same polynomial. Only the eigenspace can tell them apart, so the polynomial alone is never enough to decide diagonalisability.' },
    { sec: 'Eigenvectors', title: 'Two multiplicities', cols: ['Matrix', 'Algebraic', 'Geometric', 'Diagonalisable?'],
      rows: [['2 I  (2 × 2)', '2', '2', 'yes'], ['[[2, 1], [0, 2]]', '2', '1', 'no'], ['[[4, 1], [2, 3]]', '1 and 1', '1 and 1', 'yes'], ['[[0, 1], [0, 0]]', '2', '1', 'no']],
      firstW: 330, tip: 'Geometric ≤ algebraic always. Diagonalisable iff they are equal for every eigenvalue.',
      n: 'Step fifteen: two multiplicities. The algebraic multiplicity is how many times the root repeats. The geometric multiplicity is the dimension of the eigenspace. Geometric is never larger than algebraic. A matrix is diagonalisable exactly when the two are equal for every eigenvalue. Two times the identity: two and two, yes. The defective matrix: two and one, no. Our running example: one and one for each eigenvalue, yes. And the nilpotent zero, one, zero, zero: two and one, no.' },
    { sec: 'Eigenvectors', title: 'No real eigenvalues', viz: { kind: 'plot', x: [-3, 3], y: [-1, 6], xt: 1, yt: 1, fns: [{ f: 'x*x+1' }],
        steps: [{ k: 'a rotation by ninety degrees', note: 'R = [[0, −1], [1, 0]]: trace 0, determinant 1', col: 'blue' }, { k: 'its polynomial is', note: 'p(λ) = λ² + 1', col: 'pink' }, { k: 'never reaches zero', pt: [[0, 1, 'minimum 1']], col: 'bad', note: 'no real root: no real eigenvector' }, { k: 'over the complex numbers', note: 'λ = i and λ = −i: trace 0 and product 1 both hold', col: 'ok' }] },
      tip: 'Real matrices have complex eigenvalues in conjugate pairs.',
      n: 'Step sixteen: when there are no real eigenvalues. A rotation by ninety degrees has trace zero and determinant one. Its polynomial is lambda squared plus one. The curve never reaches zero, so there is no real eigenvalue, which makes sense, because every real vector turns. Over the complex numbers, the eigenvalues are i and minus i, and trace and determinant still hold: they add to zero and multiply to one.' },
    { sec: 'Eigenvectors', title: 'Sum and product still hold', cmd: ['# rotation R = [[0, −1], [1, 0]]', 'p(λ) = λ² + 1,  roots  i, −i', 'i + (−i) = 0 = trace            ✓', 'i · (−i) = 1 = determinant      ✓', '# real matrix: complex roots come in conjugate pairs', '# odd size real matrix: at least one real eigenvalue'],
      term: 'complex', tip: 'A real 3 × 3 matrix always has at least one real eigenvalue.',
      n: 'Step seventeen: sum and product. The rotation has roots i and minus i. Their sum is zero, matching the trace. Their product is one, matching the determinant. Remember two facts. For a real matrix, complex eigenvalues come in conjugate pairs. And so an odd sized real matrix, like three by three, always has at least one real eigenvalue, since the complex ones pair up and cannot fill an odd count.' },

    { sec: 'Diagonalisation', title: 'A equals P D P inverse', viz: { kind: 'grid', corner: 'piece', rows: ['P', 'D', 'P⁻¹', 'P D P⁻¹'], hw: 220, cols: ['value'], cw: 1100, fs: 46, rh: 92, cells: BLANK(4, 1),
        steps: [{ k: 'put the eigenvectors', set: row(['[[1, 1], [1, −2]]'], 0), hl: ['r0'], col: 'blue', note: 'columns are (1, 1) and (1, −2)' }, { k: 'the eigenvalues go on the diagonal', set: row(['diag(5, 2)'], 1), hl: ['r1'], clear: true, col: 'pink', note: 'same order as the columns of P' }, { k: 'the inverse of P', set: row(['(1/3) · [[2, 1], [1, −1]]'], 2), hl: ['r2'], clear: true, col: 'warn' }, { k: 'multiplying back', set: row(['[[4, 1], [2, 3]] = A'], 3), hl: ['r3'], clear: true, col: 'ok', note: 'verified exactly' }] },
      tip: 'Columns of P are the eigenvectors; D holds the eigenvalues in the same order.',
      n: 'Step eighteen: diagonalisation. Put the eigenvectors as the columns of P: one, one, and one, minus two. The eigenvalues go on the diagonal of D, five and two, in the same order as the columns. The inverse of P is a third of two, one, one, minus one. Multiplying back, P D P inverse gives four, one, two, three, which is A. We verified it exactly.' },
    { sec: 'Diagonalisation', title: 'The diagonalisability test', cols: ['Situation', 'Verdict'],
      rows: [['n distinct eigenvalues', 'diagonalisable'], ['Real symmetric matrix', 'always diagonalisable, orthogonally'], ['Repeated λ, geometric = algebraic', 'diagonalisable'], ['Repeated λ, geometric < algebraic', 'not diagonalisable'], ['Complex eigenvalues, real P wanted', 'not diagonalisable over the reals']],
      firstW: 560, tip: 'For each repeated eigenvalue, compare n − rank(A − λ I) with its multiplicity.',
      n: 'Step nineteen: the test. With n distinct eigenvalues, you are done: diagonalisable. A real symmetric matrix is always diagonalisable. With a repeated eigenvalue, compare the dimension of the eigenspace with the multiplicity. If they are equal, diagonalisable. If smaller, not. And a real matrix with complex eigenvalues cannot be diagonalised using real matrices, though it can over the complex numbers.' },
    { sec: 'Diagonalisation', title: 'Powers by eigenvalues', viz: { kind: 'grid', corner: 'power', rows: ['A¹', 'A²', 'A³', 'A⁴', 'A⁵', 'A⁶'], hw: 200, cols: ['trace of Aⁿ', '5ⁿ + 2ⁿ', 'match'], cw: 400, fs: 46, rh: 80, cells: BLANK(6, 3), tint: { '✓': 'ok' },
        steps: [{ k: 'multiply the matrix', set: row([7, 7, '✓'], 0), hl: ['r0'], col: 'blue', note: 'A¹: trace 7 = 5 + 2' }, { k: 'square', set: row([29, 29, '✓'], 1), hl: ['r1'], clear: true, col: 'pink', note: 'A² = [[18, 7], [14, 11]]' }, { k: 'cube', set: row([133, 133, '✓'], 2), hl: ['r2'], clear: true, col: 'warn' }, { k: 'higher powers follow', set: Object.assign(row([641, 641, '✓'], 3), row([3157, 3157, '✓'], 4), row([15689, 15689, '✓'], 5)), hl: ['r3', 'r4', 'r5'], clear: true, col: 'ok', note: 'Aⁿ has eigenvalues 5ⁿ and 2ⁿ' }] },
      tip: 'trace(Aⁿ) = sum of λⁿ. Verified by multiplying A out to the sixth power.',
      n: 'Step twenty: powers. Multiply the matrix by itself and compare the trace of each power with five to the n plus two to the n. The first power has trace seven. Square it, and the trace is twenty nine, which is twenty five plus four. Cube it: one hundred thirty three. Higher powers follow the same rule, six hundred forty one, three thousand one hundred fifty seven, and fifteen thousand six hundred eighty nine. The eigenvalues of A to the n are simply five to the n and two to the n.' },
    { sec: 'Diagonalisation', title: 'A tenth power in one line', cmd: ['A = P D P⁻¹   so   Aᵐ = P Dᵐ P⁻¹', 'eigenvalues of A¹⁰:   5¹⁰ = 9765625,   2¹⁰ = 1024', 'trace(A¹⁰) = 9765625 + 1024 = 9766649', 'det(A¹⁰)   = 10¹⁰ = 5¹⁰ · 2¹⁰', '# P and P⁻¹ cancel in the middle: P D P⁻¹ P D P⁻¹ = P D² P⁻¹'],
      term: 'powers', tip: 'Never multiply the matrix ten times. Raise the eigenvalues to the tenth.',
      n: 'Step twenty one: the payoff. Since A equals P D P inverse, the m th power is P D to the m times P inverse, because the inner P inverse and P cancel. So A to the tenth has eigenvalues five to the tenth, nine million seven hundred sixty five thousand six hundred twenty five, and two to the tenth, one thousand twenty four. Its trace is nine million seven hundred sixty six thousand six hundred forty nine, and its determinant is ten to the tenth. Never multiply a matrix ten times.' },

    { sec: 'Properties', title: 'What operations do', viz: { kind: 'grid', corner: 'matrix', rows: ['A', 'A²', 'A⁻¹', 'A + 3I', '2A', 'A² − 3A + I', 'Aᵀ'], hw: 280, cols: ['first λ', 'second λ'], cw: 400, fs: 44, rh: 72, cells: BLANK(7, 2), tint: {},
        steps: [{ k: 'start with the eigenvalues', set: row(['5', '2'], 0), hl: ['r0'], col: 'blue', note: 'A = [[4, 1], [2, 3]]' }, { k: 'square', set: row(['25', '4'], 1), hl: ['r1'], clear: true, col: 'pink', note: 'Aᵏ: λᵏ' }, { k: 'invert', set: row(['1/5', '1/2'], 2), hl: ['r2'], clear: true, col: 'pink', note: 'A⁻¹: 1/λ, needs λ ≠ 0' }, { k: 'add three times the identity', set: row(['8', '5'], 3), hl: ['r3'], clear: true, col: 'warn', note: 'A + cI: λ + c' }, { k: 'double', set: row(['10', '4'], 4), hl: ['r4'], clear: true, col: 'warn', note: 'cA: cλ' }, { k: 'any polynomial', set: row(['11', '−1'], 5), hl: ['r5'], clear: true, col: 'ok', note: 'p(A): p(λ), here 25 − 15 + 1 and 4 − 6 + 1' }, { k: 'transpose', set: row(['5', '2'], 6), hl: ['r6'], clear: true, col: 'ok', note: 'Aᵀ: the same eigenvalues' }] },
      tip: 'Eigenvectors of A, Aᵏ, A⁻¹ and A + cI are the same; only the eigenvalues change.',
      n: 'Step twenty two: what operations do. Start with the eigenvalues five and two. Square the matrix, and they become twenty five and four. Invert it, and they become one fifth and one half, which needs every eigenvalue non zero. Add three times the identity, and every eigenvalue shifts by three, to eight and five. Double the matrix, and they double. Apply any polynomial, and each eigenvalue goes through the polynomial: eleven and minus one. And the transpose keeps the same eigenvalues, though not the same eigenvectors.' },
    { sec: 'Properties', title: 'Special matrices', cols: ['Matrix type', 'Eigenvalues'],
      rows: [['Triangular or diagonal', 'the diagonal entries'], ['Real symmetric', 'all real'], ['Orthogonal', 'modulus 1: |λ| = 1'], ['Real skew-symmetric', 'zero or purely imaginary'], ['Idempotent A² = A', 'only 0 or 1'], ['Nilpotent Aᵏ = 0', 'only 0']],
      firstW: 440, tip: 'Match the type to the row before doing any algebra.',
      n: 'Step twenty three: special matrices. Triangular and diagonal matrices have their diagonal entries as eigenvalues. Real symmetric matrices have only real eigenvalues. Orthogonal matrices preserve length, so their eigenvalues have modulus one. Real skew symmetric matrices have zero or purely imaginary eigenvalues. Idempotent matrices, where A squared equals A, have only zero or one. And nilpotent matrices, where some power is zero, have only zero. Match the type first and often you need no algebra. The idempotent and nilpotent cases follow from applying the matrix twice or many times to an eigenvector: lambda squared equals lambda, or lambda to the k equals zero.' },
    { sec: 'Properties', title: 'Triangular: read the diagonal', viz: { kind: 'grid', corner: 'λ', rows: ['2', '3', '4'], hw: 150, cols: ['row of A', 'eigenvector'], cw: 640, fs: 46, rh: 100, cells: BLANK(3, 2),
        steps: [{ k: 'take a triangular matrix', set: row(['[2, 5, 1]', '(1, 0, 0)'], 0), hl: ['r0'], col: 'blue', note: 'A = [[2, 5, 1], [0, 3, 7], [0, 0, 4]]' }, { k: 'the diagonal gives the eigenvalues', set: row(['[0, 3, 7]', '(5, 1, 0)'], 1), hl: ['r1'], clear: true, col: 'ok', note: 'eigenvalues 2, 3, 4' }, { k: 'the third', set: row(['[0, 0, 4]', '(18, 7, 1)'], 2), hl: ['r2'], clear: true, col: 'ok', note: 'trace 9 and determinant 24 both match' }] },
      tip: 'det(A − λ I) is a product of diagonal terms (aᵢᵢ − λ) when A is triangular.',
      n: 'Step twenty four: triangular matrices. Take a triangular matrix with diagonal two, three, four. The diagonal gives the eigenvalues directly, because subtracting lambda I leaves a triangular determinant, which is the product of the diagonal terms. The eigenvectors are one, zero, zero, then five, one, zero, and the third is eighteen, seven, one. Trace nine and determinant twenty four match the sum and product of two, three, four.' },
    { sec: 'Properties', title: 'Symmetric: orthogonal eigenvectors', viz: { kind: 'grid', corner: 'quantity', rows: ['matrix', 'eigenvalues', 'eigenvectors', 'dot product'], hw: 240, cols: ['value'], cw: 1000, fs: 46, rh: 92, cells: BLANK(4, 1),
        steps: [{ k: 'take two one one two', set: row(['S = [[2, 1], [1, 2]]'], 0), hl: ['r0'], col: 'blue', note: 'trace 4, determinant 3' }, { k: 'has eigenvalues', set: row(['3 and 1: real, as promised'], 1), hl: ['r1'], clear: true, col: 'pink', note: 'sum 4, product 3' }, { k: 'the eigenvectors are', set: row(['(1, 1) and (1, −1)'], 2), hl: ['r2'], clear: true, col: 'warn' }, { k: 'their dot product is', set: row(['1 − 1 = 0: orthogonal'], 3), hl: ['r3'], clear: true, col: 'ok', note: 'S = Q D Qᵀ with orthonormal Q' }] },
      tip: 'Symmetric: real eigenvalues, orthogonal eigenvectors for different λ, always diagonalisable.',
      n: 'Step twenty five: symmetric matrices. Take two, one, one, two. It has eigenvalues three and one, both real as the theory promises, with sum four and product three. The eigenvectors are one, one and one, minus one. Their dot product is one minus one, zero, so they are orthogonal. That is the spectral theorem: a symmetric matrix equals Q D Q transpose with an orthonormal Q.' },
    { sec: 'Properties', title: 'Cayley-Hamilton', cmd: ['p(λ) = λ² − 7λ + 10', 'A² − 7A + 10 I = 0       (verified: zero matrix)', 'A (7I − A) = 10 I', 'A⁻¹ = (7I − A) / 10 = [[3, −1], [−2, 4]] / 10', 'check: A · [[3, −1], [−2, 4]] = 10 I     ✓', '# every matrix satisfies its own characteristic equation'],
      term: 'Cayley-Hamilton', tip: 'Use it for A⁻¹ and for high powers: reduce Aⁿ using p(A) = 0.',
      n: 'Step twenty six: Cayley Hamilton. Every matrix satisfies its own characteristic equation. For us, A squared minus seven A plus ten I is the zero matrix, which we verified. Rearranging, A times seven I minus A equals ten I, so the inverse is seven I minus A, divided by ten. That is three, minus one, minus two, four, over ten. Multiplying A by the numerator gives ten I, as required. The theorem also lets you reduce high powers: any power of A can be rewritten as a combination of A and the identity, because A squared is seven A minus ten I.' },
    { sec: 'Properties', title: 'Zero as an eigenvalue', viz: { kind: 'grid', corner: 'fact', rows: ['matrix', 'determinant', 'eigenvalues', 'verdict'], hw: 220, cols: ['value'], cw: 1000, fs: 46, rh: 92, cells: BLANK(4, 1),
        steps: [{ k: 'a singular matrix', set: row(['[[1, 2], [2, 4]]'], 0), hl: ['r0'], col: 'blue', note: 'second row is twice the first' }, { k: 'has determinant', set: row(['4 − 4 = 0'], 1), hl: ['r1'], clear: true, col: 'pink', note: 'product of eigenvalues is 0' }, { k: 'one of them is zero', set: row(['0 and 5   (trace 5)'], 2), hl: ['r2'], clear: true, col: 'warn', note: 'null vector (−2, 1): A v = 0 · v' }, { k: 'singular exactly when', set: row(['singular ⟺ 0 is an eigenvalue ⟺ det = 0'], 3), hl: ['r3'], clear: true, col: 'ok' }] },
      tip: 'Invertible iff no eigenvalue is zero. Nullity of A = geometric multiplicity of 0.',
      n: 'Step twenty seven: zero as an eigenvalue. A singular matrix like one, two, two, four has determinant zero, so the product of its eigenvalues is zero and one of them is zero. The trace is five, so the eigenvalues are zero and five. The null vector minus two, one satisfies A v equals zero times v. In short, a matrix is singular exactly when zero is an eigenvalue, and also exactly when its determinant is zero.' },
    { sec: 'Properties', title: 'Rank and nullity link', icon: 'scale',
      items: [['scale', 'Nullity of A', 'dimension of eigenspace for λ = 0'], ['hash', 'Rank = n − nullity', 'rank-nullity theorem'], ['warn', 'Rank is not the number of non-zero λ', 'true only when A is diagonalisable'], ['check', 'Idempotent matrix', 'rank = trace, since eigenvalues are 0 or 1']],
      tip: 'Idempotent trick: rank(A) = trace(A).',
      n: 'Step twenty eight: rank and nullity. The nullity of A is the dimension of the eigenspace for eigenvalue zero. The rank is n minus the nullity. Careful: the rank equals the number of non zero eigenvalues only when A is diagonalisable. A defective matrix can break that count. One useful special case: for an idempotent matrix the eigenvalues are zero or one, so the rank equals the trace.' },
    { sec: 'Properties', title: 'Similar matrices', icon: 'refresh',
      items: [['refresh', 'B = Q⁻¹ A Q', 'A and B are similar'], ['check', 'Same eigenvalues', 'same characteristic polynomial'], ['check', 'Same trace and determinant', 'also the same rank'], ['x', 'Eigenvectors differ', 'v for A becomes Q⁻¹ v for B']],
      tip: 'Similarity keeps eigenvalues, trace, determinant and rank; it does not keep eigenvectors.',
      n: 'Step twenty nine: similar matrices. If B equals Q inverse A Q, then A and B are similar. They share the same characteristic polynomial, hence the same eigenvalues, trace, and determinant, and also the same rank. But the eigenvectors differ: if v is an eigenvector of A, then Q inverse times v is one of B. Diagonalisation is just the special case where B is diagonal.' },

    { sec: 'GATE traps', title: 'Claims that sound right', cols: ['Claim', 'Verdict'],
      rows: [['A and Aᵀ have equal eigenvalues', 'true, and equal eigenvectors: false'], ['λ of A + B is λ(A) + λ(B)', 'false in general'], ['λ of A B is λ(A) · λ(B)', 'false in general'], ['A B and B A have equal eigenvalues', 'true, for square matrices'], ['Repeated λ means not diagonalisable', 'false: the identity is fine']],
      firstW: 500, tip: 'Eigenvalues add or multiply only when A and B share eigenvectors.',
      n: 'Step thirty: claims that sound right. A and its transpose have equal eigenvalues, but not equal eigenvectors. The eigenvalues of A plus B are not the sums of eigenvalues, and those of A times B are not products, except in special cases. A B and B A do have the same eigenvalues for square matrices. And a repeated eigenvalue does not imply that a matrix is not diagonalisable: the identity matrix repeats and is perfectly diagonal.' },
    { sec: 'GATE traps', title: 'A B versus B A', viz: { kind: 'grid', corner: 'matrix', rows: ['A + B', 'A B', 'B A', 'A · B'], hw: 220, cols: ['trace', 'det', 'eigenvalues'], cw: 400, fs: 46, rh: 92, cells: BLANK(4, 3),
        steps: [{ k: 'take A as before', set: row([9, 14, '2, 7'], 0), hl: ['r0'], col: 'blue', note: 'A = [[4, 1], [2, 3]], B = [[1, 2], [0, 1]]: A + B has 2 and 7, not 5 + 1 and 2 + 1' }, { k: 'the product A B', set: row([11, 10, '1, 10'], 1), hl: ['r1'], clear: true, col: 'pink', note: 'A B = [[4, 9], [2, 7]]' }, { k: 'but B A', set: row([11, 10, '1, 10'], 2), hl: ['r2'], clear: true, col: 'ok', note: 'B A = [[8, 7], [2, 3]]: same eigenvalues, different vectors' }, { k: 'not the product', set: row(['', '', '5 · 1, 2 · 1 = 5, 2'], 3), hl: ['r3'], clear: true, col: 'bad', note: 'eigenvalues of A B are 1 and 10: not the products' }] },
      tip: 'AB and BA share eigenvalues even when AB ≠ BA.',
      n: 'Step thirty one: a concrete check. Take A as before and B as one, two, zero, one, which has eigenvalue one twice. Then A plus B has eigenvalues two and seven, not the sums. The product A B has eigenvalues one and ten, trace eleven and determinant ten. But B A has the very same eigenvalues, one and ten, even though the matrices differ. And these are not the products of the eigenvalues of A and B, which would be five and two.' },
    { sec: 'GATE traps', title: 'Counting functions of eigenvalues', icon: 'bug',
      items: [['hash', 'p(A) has eigenvalues p(λ)', 'apply the polynomial to each λ'], ['warn', 'Trace of A² is sum of λ²', 'not the square of the trace'], ['warn', 'det(kA) = kⁿ det A', 'n is the matrix size'], ['hash', 'det A is the product of all λ', 'count repeated roots each time'], ['bug', 'Check zero first', 'a zero eigenvalue kills the determinant']],
      tip: 'tr(A²) = Σ λ², while (tr A)² = (Σ λ)². They are different.',
      n: 'Step thirty two: functions of eigenvalues. Any polynomial of a matrix has the polynomial of each eigenvalue as its eigenvalues. The trace of A squared is the sum of the squares of eigenvalues, not the square of the trace. The determinant of k times A is k to the n times the determinant of A, where n is the matrix size. The determinant is the product of all eigenvalues, with repeats counted. Always check for a zero eigenvalue first.' },
    { sec: 'GATE traps', title: 'Repeated but diagonalisable', cmd: ['A = [[2, 1, 1], [1, 2, 1], [1, 1, 2]]', 'trace = 6,  det = 4', 'eigenvalues 4, 1, 1:   4 + 1 + 1 = 6,  4 · 1 · 1 = 4   ✓', 'λ = 1 has TWO independent eigenvectors', '    (−1, 1, 0) and (−1, 0, 1):  diagonalisable', '# symmetric, so repeated λ cannot make it defective'],
      term: 'repeat', tip: 'Symmetric plus repeated eigenvalue is still diagonalisable.',
      n: 'Step thirty three: a repeated eigenvalue that works. Take the matrix with two on the diagonal and one elsewhere. The trace is six and the determinant is four. The eigenvalues are four, one, one: they add to six and multiply to four. The repeated eigenvalue one has two independent eigenvectors, minus one, one, zero, and minus one, zero, one. So it is diagonalisable, as every symmetric matrix must be, even with a repeated eigenvalue.' },

    { sec: 'GATE practice', title: 'Practice: from the row sums', viz: { kind: 'grid', corner: 'step', rows: ['matrix', 'row sums', 'trace', 'answer'], hw: 220, cols: ['A = [[1, 4], [2, 3]]'], cw: 1000, fs: 46, rh: 92, cells: BLANK(4, 1),
        steps: [{ k: 'both rows add to', set: row(['5 and 5'], 1), hl: ['r1'], col: 'blue', note: 'so (1, 1) is an eigenvector with λ = 5' }, { k: 'the trace is four', set: row(['1 + 3 = 4'], 2), hl: ['r2'], clear: true, col: 'pink', note: 'the other eigenvalue is 4 − 5 = −1' }, { k: 'as a check', set: row(['1 · 3 − 4 · 2 = −5 = 5 · (−1)'], 3), hl: ['r3'], clear: true, col: 'ok', note: 'eigenvalues 5 and −1' }] },
      tip: 'Row sum first, trace second, determinant as the check.',
      n: 'Step thirty four: practice. Find the eigenvalues of one, four, two, three. Both rows add to five, so five is an eigenvalue. The trace is four, so the other is four minus five, minus one. As a check, the determinant is one times three minus four times two, minus five, which equals five times minus one. The eigenvalues are five and minus one. This route needed no expansion of a characteristic polynomial at all, which is exactly why examiners prefer matrices with equal row sums.' },
    { sec: 'GATE practice', title: 'Practice: functions of a 3 × 3', cmd: ['# A is 3 × 3 with eigenvalues 1, 2, 3', 'det(A)          = 1 · 2 · 3          = 6', 'det(A⁻¹)        = 1 / 6', 'det(2A)         = 2³ · 6             = 48', 'trace(A²)       = 1 + 4 + 9          = 14', 'A² − 2A + I     eigenvalues (λ−1)²   = 0, 1, 4', 'det(A² − 2A + I) = 0 · 1 · 4         = 0'],
      term: 'practice 2', tip: 'Apply the polynomial to each λ, then multiply or add.',
      n: 'Step thirty five: a three by three with eigenvalues one, two, three. The determinant is six. The determinant of the inverse is one sixth. The determinant of two A is two cubed times six, forty eight. The trace of A squared is one plus four plus nine, fourteen. The matrix A squared minus two A plus I has eigenvalues lambda minus one, squared: zero, one, four. So its determinant is zero. Apply the polynomial to each eigenvalue, then combine.' },
    { sec: 'GATE practice', title: 'Practice: the missing eigenvalue', viz: { kind: 'array', cells: ['2', '−1', '?', '5'], label: '', cw: 260, idx: false, fs: 52,
        steps: [{ k: 'a three by three matrix', hl: [0, 1], col: 'blue', note: 'λ₁ = 2, λ₂ = −1, and the trace is 5' }, { k: 'the third eigenvalue', set: { 2: '4' }, hl: [2], clear: true, col: 'pink', note: '2 + (−1) + λ₃ = 5, so λ₃ = 4' }, { k: 'the determinant', set: { 3: '−8' }, hl: [3], clear: true, col: 'ok', note: 'cells: λ₁, λ₂, λ₃, then det = 2 · (−1) · 4 = −8' }] },
      tip: 'Two eigenvalues plus the trace give the third; then the determinant is free.',
      n: 'Step thirty six: the missing eigenvalue. A three by three matrix has eigenvalues two and minus one, and the trace is five. Then the third eigenvalue is four, since two minus one plus four is five. The determinant is two times minus one times four, which is minus eight. Two eigenvalues plus the trace give the third, and then the determinant comes free.' },
    { sec: 'GATE practice', title: 'Practice: when is it singular?', viz: { kind: 'grid', corner: 'quantity', rows: ['matrix', 'determinant', 'for k = 4', 'eigenvalues'], hw: 220, cols: ['A = [[1, 2], [2, k]]'], cw: 1000, fs: 46, rh: 92, cells: BLANK(4, 1),
        steps: [{ k: 'singular needs', set: row(['k − 4 = 0'], 1), hl: ['r1'], col: 'blue', note: 'det = k − 4' }, { k: 'so k is four', set: row(['[[1, 2], [2, 4]]'], 2), hl: ['r2'], clear: true, col: 'pink' }, { k: 'the trace is five', set: row(['0 and 5'], 3), hl: ['r3'], clear: true, col: 'ok', note: 'one eigenvalue is 0, and 0 + λ = 5' }] },
      tip: 'Singular means zero is an eigenvalue: determinant zero.',
      n: 'Step thirty seven: for which k is one, two, two, k singular? Singular needs the determinant, k minus four, to be zero. So k is four. The matrix becomes one, two, two, four. The trace is five, so the eigenvalues are zero and five. Singular means zero is an eigenvalue, and that is the same as determinant zero.' },
    { sec: 'GATE practice', title: 'Practice: diagonalisable?', cmd: ['(a) [[3, 1], [0, 3]]    λ = 3 twice, one eigenvector     ✗', '(b) [[3, 0], [0, 3]]    λ = 3 twice, two eigenvectors    ✓', '(c) [[1, 3], [3, 1]]    symmetric, λ = 4 and −2          ✓', '(d) [[0, −1], [1, 0]]   λ = i, −i: no real eigenvalues     ✗ (over R)', '# eigenvalues and eigenspace dimensions verified exactly'],
      term: 'practice 5', tip: 'Compare eigenspace dimension to multiplicity; symmetric always passes.',
      n: 'Step thirty eight: which are diagonalisable? Matrix a, three, one, zero, three: three twice with one eigenvector, so no. Matrix b, three times the identity: three twice with two eigenvectors, yes. Matrix c, one, three, three, one: symmetric, with eigenvalues four and minus two, yes. Matrix d, the rotation: complex eigenvalues, so not over the reals. Each eigenspace dimension was verified exactly.' },
    { sec: 'GATE practice', title: 'Practice: orthogonal eigenvectors', viz: { kind: 'grid', corner: 'quantity', rows: ['matrix', 'eigenvalues', 'eigenvectors', 'dot product'], hw: 240, cols: ['S = [[5, 2], [2, 2]]'], cw: 1000, fs: 46, rh: 92, cells: BLANK(4, 1),
        steps: [{ k: 'the trace is seven', set: row(['5 + 2 = 7, det = 10 − 4 = 6'], 0), hl: ['r0'], col: 'blue', note: 'two numbers adding to 7 with product 6' }, { k: 'so the eigenvalues are', set: row(['6 and 1'], 1), hl: ['r1'], clear: true, col: 'pink' }, { k: 'the eigenvectors are', set: row(['(2, 1) and (−1, 2)'], 2), hl: ['r2'], clear: true, col: 'warn', note: 'S(2, 1) = (12, 6) = 6 · (2, 1)' }, { k: 'so they are orthogonal', set: row(['−2 + 2 = 0'], 3), hl: ['r3'], clear: true, col: 'ok', note: 'a symmetric matrix always does this' }] },
      tip: 'Symmetric matrix: eigenvectors for different eigenvalues have zero dot product.',
      n: 'Step thirty nine: the symmetric matrix five, two, two, two. The trace is seven and the determinant is six, so the eigenvalues are six and one. The eigenvectors are two, one, and minus one, two. Check the first: S times two, one is twelve, six, six times the vector. And the dot product is minus two plus two, zero, so they are orthogonal, as every symmetric matrix guarantees.' },
    { sec: 'GATE practice', title: 'Practice: inverse and shift', viz: { kind: 'grid', corner: 'matrix', rows: ['A', 'A⁻¹', 'A + 3I', '(A + 3I)⁻¹'], hw: 280, cols: ['first λ', 'second λ'], cw: 400, fs: 46, rh: 92, cells: BLANK(4, 2),
        steps: [{ k: 'the eigenvalues of', set: row(['5', '2'], 0), hl: ['r0'], col: 'blue', note: 'A = [[4, 1], [2, 3]]' }, { k: 'the inverse has', set: row(['1/5', '1/2'], 1), hl: ['r1'], clear: true, col: 'pink', note: 'trace 7/10 and determinant 1/10' }, { k: 'adding three', set: row(['8', '5'], 2), hl: ['r2'], clear: true, col: 'warn', note: 'trace 13, determinant 40' }, { k: 'and inverting that', set: row(['1/8', '1/5'], 3), hl: ['r3'], clear: true, col: 'ok', note: 'compose the rules in order' }] },
      tip: 'Compose the rules in order: shift first, then invert.',
      n: 'Step forty: compose the rules. The eigenvalues of A are five and two. The inverse has one fifth and one half, with trace seven tenths and determinant one tenth. Adding three to the matrix makes the eigenvalues eight and five, trace thirteen, determinant forty. And inverting that gives one eighth and one fifth. Compose the rules in the order the question applies them.' },
    { sec: 'GATE practice', title: 'Five-second shortcuts', items: [['zap', 'Σ λ = trace, Π λ = det', '2 × 2: roots of λ² − tr λ + det'], ['zap', 'Triangular', 'eigenvalues are the diagonal'], ['zap', 'p(A) has eigenvalues p(λ)', 'powers, inverses, shifts, scalings'], ['zap', 'Row sums equal s', 'then s is an eigenvalue'], ['zap', 'Symmetric', 'real λ, orthogonal vectors, diagonalisable']],
      tip: 'These five lines answer most GATE eigenvalue questions.',
      n: 'Step forty one: shortcuts. The sum of eigenvalues is the trace and the product is the determinant, so a two by two matrix is a quick factorisation. A triangular matrix shows its eigenvalues on the diagonal. A polynomial of A has the polynomial of each eigenvalue. Equal row sums give that sum as an eigenvalue. And a symmetric matrix has real eigenvalues, orthogonal eigenvectors, and is always diagonalisable.' },
    { sec: 'GATE practice', title: 'Exam strategy', cols: ['Question type', 'Fastest method'],
      rows: [['Eigenvalues of a 2 × 2', 'trace and determinant, factor mentally'], ['Eigenvalues of a 3 × 3', 'triangular? row sums? else polynomial'], ['Function of A', 'apply it to each eigenvalue'], ['Diagonalisable?', 'distinct, or compare multiplicities'], ['Determinant or trace question', 'product and sum of eigenvalues']],
      firstW: 500, tip: 'Look for structure before expanding any determinant.',
      n: 'Step forty two: exam strategy. For two by two eigenvalues, use the trace and determinant and factor mentally. For three by three, first ask whether it is triangular or has equal row sums; otherwise write the polynomial. For a function of A, apply it to each eigenvalue. For diagonalisability, check distinct eigenvalues, or compare multiplicities. And for determinant or trace questions, use the product and sum of eigenvalues.' },
    { sec: 'GATE practice', title: 'Common distractors', cols: ['Distractor', 'Why it fails'],
      rows: [['Eigenvectors of Aᵀ equal those of A', 'only the eigenvalues agree'], ['Trace of A² = (trace of A)²', 'it is the sum of λ², not (Σ λ)²'], ['det(2A) = 2 det A', 'it is 2ⁿ det A for n × n'], ['Real matrix, real eigenvalues', 'rotations have none'], ['Same polynomial, same behaviour', 'defective versus diagonal']],
      firstW: 520, tip: 'Four-option questions often include exactly one of these.',
      n: 'Step forty three: the distractors that appear in answer options. Eigenvectors of A transpose equal those of A: only the eigenvalues agree. Trace of A squared equals trace squared: it is the sum of squared eigenvalues. Determinant of two A equals two times the determinant: it is two to the n. A real matrix has real eigenvalues: rotations have none. Same polynomial, same behaviour: a defective matrix disagrees with a diagonal one.' },
    { sec: 'GATE practice', title: 'Where this leads next', nodes: [['gauge', 'Eigenvalues', 'this video'], ['star', 'Vector spaces', 'next topic'], ['chart', 'PCA', 'machine learning'], ['route', 'Markov chains', 'probability and PageRank']],
      edges: ['then', 'applies to', 'and'], tip: 'Eigenvalue one of a stochastic matrix gives the long-run Markov distribution.',
      n: 'Step forty four: where this leads. Next come vector spaces and their dimension, which underpin the eigenspaces we used. Eigenvalues also drive principal component analysis in machine learning, where the largest eigenvalues of a covariance matrix mark the most important directions. And Markov chains and PageRank rely on the eigenvalue one of a stochastic matrix, whose eigenvector is the long run distribution.' },

    { type: 'mistakes', rows: [['Expanding a determinant when trace and det suffice', 'For 2 × 2 the sum and product are enough'], ['Calling the zero vector an eigenvector', 'Eigenvectors must be non-zero'], ['Assuming repeated λ means not diagonalisable', 'Compare eigenspace dimension to multiplicity'], ['Using tr(A²) = (tr A)²', 'It is the sum of squared eigenvalues']],
      n: 'Four common mistakes. Expanding a determinant when trace and determinant are enough: for a two by two matrix the sum and product settle it. Calling the zero vector an eigenvector: eigenvectors must be non zero. Assuming a repeated eigenvalue means not diagonalisable: compare the eigenspace dimension to the multiplicity. And using trace of A squared equals trace squared, when it is the sum of squared eigenvalues.' },
    { type: 'repos', chip: 'Practice', title: 'Practise with these', repos: [['GATE CSE previous papers', 'Eigenvalue and diagonalisation questions', '', 'book'], ['gateoverflow.in', 'Tags: eigen-value, linear-algebra', '', 'comment'], ['NPTEL: Linear Algebra', 'Eigenvalues and diagonalisation lectures', '', 'play'], ['Strang, Linear Algebra', 'Chapter 6: eigenvalues and eigenvectors', '', 'bookmark'], ['Python', 'Check any answer with fractions and a polynomial', '', 'code'], ['../interactive/m1-discrete.html', 'Your interactive discrete maths module', '', 'lightbulb']],
      n: 'Here is where to practise. GATE previous papers on eigenvalues and diagonalisation. GATE Overflow, with tags for eigenvalue and linear algebra. The NPTEL linear algebra lectures. Chapter six of Strang. A few lines of Python, to check any answer with exact fractions. And your interactive discrete maths module. Screenshot this frame.' },
    { type: 'recap', points: ['A v = λ v; roots of det(A − λ I) = 0; trace = Σ λ, det = Π λ', '2 × 2: roots of λ² − tr · λ + det; row sums equal s gives eigenvalue s', 'Diagonalisable iff geometric = algebraic multiplicity for every λ; A = P D P⁻¹, Aᵐ = P Dᵐ P⁻¹', 'p(A) has eigenvalues p(λ); A⁻¹ has 1/λ; triangular: the diagonal; Aᵀ: same λ', 'Symmetric: real λ, orthogonal vectors; singular iff 0 is an eigenvalue'],
      n: 'Let us recap. An eigenvector satisfies A v equals lambda v, the eigenvalues are roots of the determinant of A minus lambda I, and the trace is their sum while the determinant is their product. For two by two, factor lambda squared minus trace lambda plus determinant, and equal row sums give an eigenvalue. A matrix is diagonalisable when the geometric multiplicity equals the algebraic for every eigenvalue, and then powers follow from P D to the m P inverse. Polynomials, inverses, and triangular matrices act on eigenvalues simply. Symmetric means real and orthogonal, and singular means zero is an eigenvalue. Follow for more, and comment EIGEN if this helped.' },
  ],
};
